content:
{
  "code": ":root {
  --color-ivory: #F9F6F1;
  --color-terracotta: #C27C5A;
  --color-charcoal: #2D2D2D;
  --color-charcoal-light: #4A4A4A;
  --color-bg: #FFFFFF;
  --color-border: #E5E0D8;
  --color-text-secondary: #666666;

  --font-body: 'Noto Sans KR', sans-serif;
  --font-display: 'Noto Sans KR', sans-serif;

  --space-xs: 8px;
  --space-sm: 12px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 48px;
  --space-xxl: 64px;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --max-width: 1120px;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.5;
  font-weight: 500;
  color: var(--color-charcoal);
  background-color: var(--color-ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.masthead {
  padding: var(--space-xl) var(--space-lg);
  text-align: center;
  background-color: var(--color-ivory);
}

.masthead h1 {
  font-family: var(--font-display);
  font-size: 36px;
  line-height: 1.2;
  font-weight: 700;
  margin: 0 0 var(--space-xs) 0;
  color: var(--color-charcoal);
}

.subtitle {
  font-size: 18px;
  color: var(--color-charcoal-light);
  margin: 0;
  font-weight: 500;
}

main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.editorial-hero {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
  min-height: 400px;
  margin-bottom: var(--space-xxl);
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: var(--space-xl);
}

.pottery-illustration {
  width: 100%;
  height: 100%;
  min-height: 300px;
  background-color: #F2EBE3;
  border-radius: var(--radius-md);
  position: relative;
}

.pottery-illustration::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 60%;
  height: 60%;
  border-radius: 50%;
  background-color: #E8DFD3;
  box-shadow: inset 0 10px 20px rgba(0,0,0,0.05);
}

.pottery-illustration::after {
  content: '';
  position: absolute;
  top: 40%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 40%;
  height: 40%;
  border-radius: 40% 40% 10% 10%;
  background-color: #D6CBB9;
}

.hero-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.hero-content h2 {
  font-family: var(--font-display);
  font-size: 36px;
  line-height: 1.2;
  font-weight: 700;
  margin: 0 0 var(--space-md) 0;
  color: var(--color-charcoal);
}

.hero-content p {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin: 0;
  font-weight: 500;
}

.search-section {
  margin-bottom: var(--space-xl);
  position: relative;
}

.search-section label {
  display: none;
}

#search {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  font-size: 16px;
  font-family: var(--font-body);
  font-weight: 500;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg);
  color: var(--color-charcoal);
  box-sizing: border-box;
}

#search:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.1);
}

#search::placeholder {
  color: #A0A0A0;
}

.catalogue {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-bottom: var(--space-xxl);
}

.catalogue-card {
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.catalogue-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.05);
}

.card-illustration {
  height: 160px;
  background-color: #F2EBE3;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-md);
  position: relative;
}

.card-illustration::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50%;
  height: 50%;
  border-radius: 50%;
  background-color: #E8DFD3;
}

.catalogue-card h3 {
  font-family: var(--font-display);
  font-size: 20px;
  line-height: 1.3;
  font-weight: 700;
  margin: 0 0 var(--space-xs) 0;
  color: var(--color-charcoal);
}

.card-category {
  display: inline-block;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-terracotta);
  background-color: rgba(194, 124, 90, 0.1);
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-sm);
}

.card-description {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0 0 var(--space-md) 0;
  line-height: 1.6;
  flex-grow: 1;
}

.card-meta {
  display: flex;
  gap: var(--space-sm);
  font-size: 14px;
  color: var(--color-charcoal-light);
  margin-bottom: var(--space-md);
}

.card-price {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-charcoal);
  margin-bottom: var(--space-md);
}

.btn-detail {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  background-color: transparent;
  border: 1px solid var(--color-terracotta);
  color: var(--color-terracotta);
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.btn-detail:hover {
  background-color: var(--color-terracotta);
  color: var(--color-bg);
}

.btn-detail:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.2);
}

.empty-state {
  grid-column: 1 / -1;
  text-align: center;
  padding: var(--space-xxl);
  color: var(--color-text-secondary);
  font-size: 16px;
}

.booking-section {
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  margin-bottom: var(--space-xxl);
}

.booking-section h2 {
  font-family: var(--font-display);
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
  margin: 0 0 var(--space-lg) 0;
  color: var(--color-charcoal);
}

#selected-class-info {
  background-color: #F9F6F1;
  padding: var(--space-md);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
}

#selected-class-info h3 {
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 var(--space-xs) 0;
}

#selected-class-info p {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0 0 var(--space-xs) 0;
}

.selected-price {
  font-weight: 700 !important;
  color: var(--color-charcoal) !important;
  margin-top: var(--space-sm) !important;
}

.form-group {
  margin-bottom: var(--space-md);
}

.form-group label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-charcoal-light);
  margin-bottom: var(--space-xs);
}

#guest, #date {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: 16px;
  font-family: var(--font-body);
  font-weight: 500;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg);
  color: var(--color-charcoal);
  box-sizing: border-box;
}

#guest:focus, #date:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.1);
}

#slot {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: 16px;
  font-family: var(--font-body);
  font-weight: 500;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg);
  color: var(--color-charcoal);
  box-sizing: border-box;
}

#slot:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.1);
}

.btn-primary {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  background-color: var(--color-charcoal);
  color: var(--color-bg);
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  margin-top: var(--space-sm);
}

.btn-primary:hover {
  background-color: #1A1A1A;
}

.btn-primary:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(45, 45, 45, 0.2);
}

#confirmation {
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  margin-bottom: var(--space-xxl);
}

#confirmation h2 {
  font-family: var(--font-display);
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
  margin: 0 0 var(--space-lg) 0;
  color: var(--color-charcoal);
}

.confirm-row {
  display: flex;
  justify-content: space-between;
  padding: var(--space-sm) 0;
  border-bottom: 1px solid var(--color-border);
}

.confirm-row:last-child {
  border-bottom: none;
}

.confirm-row span:first-child {
  font-weight: 600;
  color: var(--color-charcoal-light);
}

.btn-secondary {
  padding: var(--space-sm) var(--space-md);
  background-color: transparent;
  border: 1px solid var(--color-border);
  color: var(--color-text-secondary);
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  margin-top: var(--space-lg);
}

.btn-secondary:hover {
  background-color: #F2EBE3;
  color: var(--color-charcoal);
}

.btn-secondary:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.2);
}

.demo-disclosure {
  text-align: center;
  padding: var(--space-lg) 0;
  color: var(--color-text-secondary);
  font-size: 14px;
  border-top: 1px solid var(--color-border);
  margin-top: var(--space-xxl);
}

@media (max-width: 1024px) {
  .editorial-hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .pottery-illustration {
    height: 240px;
  }

  .catalogue {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .masthead h1 {
    font-size: 28px;
  }

  .hero-content h2 {
    font-size: 28px;
  }

  .catalogue {
    grid-template-columns: 1fr;
  }

  .editorial-hero {
    padding: var(--space-lg);
  }

  main {
    padding: 0 var(--space-md);
  }
}

@media (max-width: 320px) {
  .masthead {
    padding: var(--space-md);
  }

  .masthead h1 {
    font-size: 24px;
  }

  .subtitle {
    font-size: 16px;
  }

  .hero-content h2 {
    font-size: 24px;
  }

  .editorial-hero {
    padding: var(--space-md);
    gap: var(--space-md);
  }

  .pottery-illustration {
    height: 180px;
  }

  .catalogue-card {
    padding: var(--space-md);
  }

  .booking-section, #confirmation {
    padding: var(--space-md);
  }

  main {
    padding: 0 var(--space-sm);
  }
}"
}
